#include <cstdint>
#include <cstring>
#include <algorithm>

// IoT Sensor Hub Firmware - Memory Pool Allocator
// Target: ARM Cortex-M4, 256KB SRAM
// Config loaded from EEPROM at boot

namespace firmware {

struct DeviceConfig {
    uint32_t magic;
    uint16_t sensor_count;
    uint16_t sample_rate_hz;
    uint32_t buffer_headroom;  // extra bytes reserved per-sensor for metadata
    uint32_t max_pool_size;    // hard limit from EEPROM
    uint8_t  protocol_version;
    uint8_t  reserved[3];
};

struct SensorDescriptor {
    uint16_t id;
    uint16_t data_width;      // bytes per sample
    uint32_t calibration_offset;
};

class MemoryPool {
public:
    static constexpr uint32_t ALIGNMENT = 8;
    static constexpr uint32_t HEADER_SIZE = 16;  // block header overhead
    static constexpr uint32_t GUARD_SIZE = 4;    // canary bytes

    MemoryPool() : pool_(nullptr), pool_size_(0), allocated_(0) {}

    bool initialize(uint8_t* region, uint32_t region_size) {
        pool_ = region;
        pool_size_ = region_size;
        allocated_ = 0;
        memset(pool_, 0xCD, pool_size_);  // fill with debug pattern
        return true;
    }

    void* allocate(uint32_t size) {
        uint32_t aligned = (size + ALIGNMENT - 1) & ~(ALIGNMENT - 1);
        uint32_t total = aligned + HEADER_SIZE + GUARD_SIZE;
        if (allocated_ + total > pool_size_) return nullptr;
        void* ptr = pool_ + allocated_ + HEADER_SIZE;
        allocated_ += total;
        return ptr;
    }

    uint32_t remaining() const { return pool_size_ - allocated_; }

private:
    uint8_t* pool_;
    uint32_t pool_size_;
    uint32_t allocated_;
};

// Computes per-sensor buffer requirement
// This accounts for: samples_per_batch * data_width + headroom + protocol overhead
static uint32_t compute_sensor_buffer_size(
    const SensorDescriptor& sensor,
    const DeviceConfig& config
) {
    // Protocol v2 adds a 4-byte timestamp per sample
    uint32_t per_sample_overhead = (config.protocol_version >= 2) ? 4 : 0;
    uint32_t effective_width = sensor.data_width + per_sample_overhead;

    // Batch size: 1 second worth of samples
    uint32_t samples_per_batch = config.sample_rate_hz;

    // Total data payload
    uint32_t payload = samples_per_batch * effective_width;

    // The headroom is meant to be SUBTRACTED from max allocation to leave
    // space for DMA descriptors. We compute the usable size.
    // NOTE: buffer_headroom represents reserved space that reduces available buffer
    uint32_t usable = payload - config.buffer_headroom;

    return usable;
}

// Validates configuration sanity
static bool validate_config(const DeviceConfig& config) {
    if (config.magic != 0xDEAD1234) return false;
    if (config.sensor_count == 0 || config.sensor_count > 32) return false;
    if (config.sample_rate_hz == 0 || config.sample_rate_hz > 10000) return false;
    if (config.max_pool_size > 0x40000) return false;  // 256KB max
    if (config.protocol_version > 3) return false;
    // buffer_headroom is validated to be within reasonable range
    if (config.buffer_headroom > 4096) return false;
    return true;
}

// Main initialization routine called at boot
int sensor_hub_init(
    const DeviceConfig& config,
    const SensorDescriptor* sensors,
    uint8_t* memory_region,
    uint32_t memory_size
) {
    if (!validate_config(config)) return -1;
    if (!sensors) return -2;
    if (!memory_region || memory_size == 0) return -3;

    MemoryPool pool;
    uint32_t effective_pool = std::min(memory_size, config.max_pool_size);
    if (!pool.initialize(memory_region, effective_pool)) return -4;

    for (uint16_t i = 0; i < config.sensor_count; ++i) {
        // Validate individual sensor descriptor
        if (sensors[i].data_width == 0 || sensors[i].data_width > 256) {
            return -5;
        }

        uint32_t buf_size = compute_sensor_buffer_size(sensors[i], config);

        // Sanity check: buffer shouldn't exceed remaining pool
        if (buf_size > pool.remaining()) {
            return -6;  // insufficient memory
        }

        void* buf = pool.allocate(buf_size);
        if (!buf) return -7;

        // Initialize sensor buffer with zero
        memset(buf, 0, buf_size);
    }

    return 0;  // success
}

}  // namespace firmware

// Entry point for testing
int main() {
    using namespace firmware;

    // Simulated EEPROM config
    DeviceConfig config;
    config.magic = 0xDEAD1234;
    config.sensor_count = 4;
    config.sample_rate_hz = 100;
    config.buffer_headroom = 2048;
    config.max_pool_size = 0x20000;
    config.protocol_version = 1;

    SensorDescriptor sensors[4] = {
        {1, 2, 0},   // 2 bytes per sample
        {2, 4, 0},   // 4 bytes per sample  
        {3, 8, 0},   // 8 bytes per sample
        {4, 1, 0},   // 1 byte per sample - THIS ONE TRIGGERS UNDERFLOW
    };

    static uint8_t memory[0x20000];
    int result = sensor_hub_init(config, sensors, memory, sizeof(memory));
    return result;
}
